WITH with_dims AS (SELECT e.*, p.device, p.country, p.browser FROM web_events e INNER JOIN sessions p ON e.session_id = p.id) SELECT DATE_TRUNC('YEAR', event_time) AS year_start, DATE_TRUNC('QUARTER', event_time) AS quarter_start, CASE WHEN duration_sec >= 538 THEN 'HIGH' ELSE 'LOW' END AS duration_sec_tier, BIT_AND(duration_sec) AS duration_sec_bit_and, COUNT(CASE WHEN device = 'tablet' THEN 1 END) AS tablet_count, MIN(event_time) AS first_seen, ROUND(SUM(duration_sec) / NULLIF(COUNT(CASE WHEN page = '/product' THEN 1 END), 0), 2) AS duration_sec_per_product, GROUPING(DATE_TRUNC('YEAR', event_time)) AS grouping_level FROM with_dims GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', event_time), DATE_TRUNC('QUARTER', event_time), CASE WHEN duration_sec >= 538 THEN 'HIGH' ELSE 'LOW' END), (DATE_TRUNC('YEAR', event_time), DATE_TRUNC('QUARTER', event_time)), (DATE_TRUNC('YEAR', event_time)), ()) HAVING COUNT(CASE WHEN device = 'tablet' THEN 1 END) > 1
